function buscarParte(parte, tipo) {
  if (!parte) return null;
  if (parte.mimeType === tipo && parte.body?.data) return parte.body.data;
  for (const p of (parte.parts || [])) {
    const r = buscarParte(p, tipo);
    if (r) return r;
  }
  return null;
}

function aTexto(html) {
  return html
    .replace(/<style[\s\S]*?<\/style>/gi, ' ')
    .replace(/<script[\s\S]*?<\/script>/gi, ' ')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&')
    .replace(/&aacute;/g, 'á').replace(/&eacute;/g, 'é').replace(/&iacute;/g, 'í')
    .replace(/&oacute;/g, 'ó').replace(/&uacute;/g, 'ú').replace(/&ntilde;/g, 'ñ')
    .replace(/\s+/g, ' ').trim();
}

const c = $json;

let cuerpo = '';
if (typeof c.html === 'string' && c.html) {
  cuerpo = aTexto(c.html);
} else if (typeof c.text === 'string' && c.text) {
  cuerpo = c.text.replace(/\s+/g, ' ').trim();
} else {
  const payload = c.payload || {};
  const data = buscarParte(payload, 'text/html') || buscarParte(payload, 'text/plain') || payload.body?.data || null;
  const html = data ? Buffer.from(data.replace(/-/g, '+').replace(/_/g, '/'), 'base64').toString('utf-8') : '';
  cuerpo = aTexto(html);
}

const cab = c.payload?.headers || [];
const asunto = c.subject || c.Subject || (cab.find(h => (h.name || '').toLowerCase() === 'subject') || {}).value || '';

let ms = Number(c.internalDate);
if (!Number.isFinite(ms)) ms = c.date ? new Date(c.date).getTime() : NaN;
if (!Number.isFinite(ms)) ms = Date.now();
const fecha = new Date(ms - 5 * 60 * 60 * 1000).toISOString().slice(0, 10);   // hora de Colombia (UTC-5)

return { json: { messageId: c.id || c.messageId || '', fecha, ms, texto: ('Asunto: ' + asunto + '. ' + cuerpo).slice(0, 4000) } };

const crudo = $json.content?.[0]?.text || $json.text || '';
const base = $('Limpiar').item.json;

let p = null;
try { p = JSON.parse(crudo.replace(/```json|```/g, '').trim()); } catch (e) { p = null; }

const CATEGORIAS = ['Hogar', 'Hijo', 'Carro', 'Alimentación', 'Servicios', 'Salud', 'Salidas', 'Ahorro', 'Otros', 'Tarjetas'];
const fmt = n => String(n).replace(/\B(?=(\d{3})+(?!\d))/g, '.');
const cus = (base.texto.match(/CUS:?\s*(\d{5,})/i) || [])[1] || null;

let valido = false, monto = null, fecha = base.fecha;
const concepto = String(p?.concepto || '').trim().slice(0, 60);
const categoria = CATEGORIAS.includes(p?.categoria) ? p.categoria : 'Otros';

if (p && concepto && Number.isFinite(Number(p.monto)) && Number(p.monto) > 0 && cus) {
  monto = Math.round(Number(p.monto));
  valido = base.texto.includes(fmt(monto));          // el monto tiene que estar escrito en el correo
  const m = String(p.fecha || '').match(/^(\d{2})\/(\d{2})\/(\d{4})$/);
  if (m && base.texto.includes(p.fecha)) fecha = m[3] + '-' + m[2] + '-' + m[1];
}

return { json: { valido, concepto, categoria, monto, fecha, cus, notas: cus ? 'PSE · CUS ' + cus : '', messageId: base.messageId, ms: base.ms } };

// Pagos que pasaron la validación
const nuevos = $('If').all().map(i => i.json);
// Todo lo que ya está en Movimientos
const filas = $input.all().map(i => i.json).filter(f => f && f.property_monto !== undefined);
const dias = s => Math.floor(new Date(String(s).slice(0, 10) + 'T00:00:00Z').getTime() / 86400000);

const usadas = new Set();   // cada pago anotado a mano solo "cancela" a un pago del correo
const vistos = new Set();   // el mismo pago repetido dentro de esta tanda (por CUS)
const salida = [];

for (const c of nuevos) {
  const clave = c.cus || c.messageId;
  if (vistos.has(clave)) continue;
  vistos.add(clave);

  // 1) este mismo pago (mismo CUS) ya lo registró el flujo
  if (c.cus && filas.some(f => String(f.property_notas || '').includes(c.cus))) continue;

  // 2) ya lo anotaron a mano: mismo valor en los mismos días (cada fila a mano se usa una sola vez)
  const idx = filas.findIndex((f, i) =>
    !usadas.has(i) &&
    !String(f.property_notas || '').includes('PSE · CUS') &&
    Number(f.property_monto) === c.monto &&
    f.property_fecha?.start &&
    Math.abs(dias(f.property_fecha.start) - dias(c.fecha)) <= 5
  );
  if (idx >= 0) { usadas.add(idx); continue; }

  salida.push({ json: c });
}

// se crean de más antiguo a más nuevo (así "Creado" queda en el mismo orden que los pagos)
salida.sort((a, b) => String(a.json.fecha).localeCompare(String(b.json.fecha)) || (a.json.ms || 0) - (b.json.ms || 0));
return salida;
